-- 2026-11-24 每日收录：CivClicker、Mines、Driven Wild、Z-Type、n-gon，均为 embed（站内打开原作）。
-- 只插入，不改已有行；INSERT OR IGNORE 防止与本地 jiwan.sql 重复。

INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('civclicker', 'CivClicker', 'CivClicker', 'civclicker civ clicker wenming dianji fangzhi cunluo katherine stark kastark', 'Katherine Stark', '', '', NULL, '', 0, 2014, 'idle', '["放置","策略"]', 40, 0.1, 'clicker', 'https://kastark.co.uk/games/civclicker/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '点开采集，慢慢把一个聚落养成文明', '一款放置增量游戏：先自己采集食物、木材和石料，再派出工人、盖房子、研究神祇与征伐，把一个小村落发展成文明。', 'An incremental idle game: gather food, wood and stone yourself, then assign workers, build, worship and conquer as a tiny settlement grows into a civilization.', '由 Katherine Stark 制作，2014 年起在 kastark.co.uk/games/civclicker 公开发布，源码以 GPL 许可发布。原页托管在 kastark.co.uk/games/civclicker，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。', 'Made by Katherine Stark and published at kastark.co.uk/games/civclicker since 2014; the source is released under the GPL. Hosted at kastark.co.uk/games/civclicker; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed.', 'assets/posters/civclicker.jpg', 1280, 800, 'center', '["assets/posters/civclicker.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -53, 1795485600000, 'Click to gather, and slowly grow a settlement into a civilization.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('tatham-mines', 'Mines', 'Mines', 'mines tatham saolei youxi simon tatham portable puzzle collection', 'Simon Tatham', '', '', NULL, '', 0, 2005, 'puzzle', '["益智","扫雷"]', 210, 0.06, 'story', 'https://www.chiark.greenend.org.uk/~sgtatham/puzzles/js/mines.html', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '翻开安全的格子，把藏着的地雷避过去', '一款扫雷：点开没有地雷的格子，根据数字推断其余位置，把整张盘面安全地揭开。', 'A Minesweeper-style puzzle: open cells that do not contain mines, use the numbers to deduce the rest, and clear the board safely.', '由 Simon Tatham 制作，是 Portable Puzzle Collection 中的一款，2005 年起在 chiark.greenend.org.uk 公开发布，源码以 MIT 许可发布。原页托管在 chiark.greenend.org.uk，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Simon Tatham as part of his Portable Puzzle Collection, published at chiark.greenend.org.uk since 2005, and released under the MIT License. Hosted at chiark.greenend.org.uk; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/tatham-mines.jpg', 1280, 800, 'center', '["assets/posters/tatham-mines.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -52, 1795485600000, 'Open the safe cells and keep clear of the hidden mines.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('driven-wild', 'Driven Wild', 'DR1V3N WILD', 'driven wild dr1v3n wild jiasu jingsu binhaigonglu frank force killedbyapixel js13k drive13k', 'Frank Force (KilledByAPixel)', '', '', NULL, '', 0, 2024, 'action', '["竞速","动作"]', 25, 0.16, 'io', 'https://killedbyapixel.github.io/Drive13K/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '沿着海边公路一路往前开，看看能开过几关', '一款街机竞速：用方向键或鼠标开车，穿过十个风格不同的路段，尽可能开得更远、更快。', 'An arcade racer: steer with the arrow keys or the mouse, drive through ten distinct stages, and go as far and as fast as you can.', '由 Frank Force（KilledByAPixel）制作，2024 年参加 JS13K 并在 killedbyapixel.github.io/Drive13K 公开发布。原页托管在 killedbyapixel.github.io/Drive13K，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Frank Force (KilledByAPixel) for JS13K 2024 and published at killedbyapixel.github.io/Drive13K. Hosted at killedbyapixel.github.io/Drive13K; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/driven-wild.jpg', 1280, 800, 'center', '["assets/posters/driven-wild.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -51, 1795485600000, 'Drive the coastal highway and see how many stages you can clear.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('ztype', 'Z-Type', 'Z-Type', 'ztype z-type daziji sheji dazi feichuan phoboslab dominic szablewski andreas loesch', 'Dominic Szablewski (PhobosLab)', '', '', NULL, '', 0, 2011, 'action', '["射击","打字"]', 200, 0.12, 'io', 'https://phoboslab.org/ztype/v1.html', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '对着飞来的飞船打字，把它们打下来', '一款打字射击：选普通或专家模式，输入敌人身上的单词把飞船打下来，看自己能撑过多久。', 'A typing shooter: pick Normal or Expert, type the words on incoming ships to shoot them down, and see how long you last.', '由 Dominic Szablewski（PhobosLab）制作，Andreas Loesch 负责音乐，2011 年起在 phoboslab.org/ztype 公开发布。现行带广告的版本在 zty.pe；即玩打开的是作者在 phoboslab.org/ztype/v1.html 托管的原作页面。原页不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Dominic Szablewski (PhobosLab), with music by Andreas Loesch, and published at phoboslab.org/ztype since 2011. The current ad-supported edition is at zty.pe; Jiwan opens the original page hosted at phoboslab.org/ztype/v1.html. It is not a Jiwan original. It opens here. No account needed.', 'assets/posters/ztype.jpg', 1280, 800, 'center', '["assets/posters/ztype.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -50, 1795485600000, 'Type the words on incoming ships to shoot them down.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('n-gon', 'n-gon', 'n-gon', 'n-gon ngon n gon wuli pingtai sheji roguelike landgreen', 'Landgreen', '', '', NULL, '', 0, 2019, 'action', '["动作","射击"]', 140, 0.08, 'io', 'https://landgreen.github.io/n-gon/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '在物理关卡里跑跳射击，一关一关往下打', '一款物理平台射击：用 WASD 移动、鼠标瞄准开火，在程序生成的关卡里收集枪械和能力，尽量走得更远。', 'A physics platformer-shooter: move with WASD, aim and fire with the mouse, pick up guns and fields, and push farther through procedurally built levels.', '由 Landgreen 制作，2019 年起在 landgreen.github.io/n-gon 公开发布，源码以 GPL-3.0 许可在 GitHub 发布。原页托管在 landgreen.github.io/n-gon，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Landgreen and published at landgreen.github.io/n-gon since 2019; the source is GPL-3.0 on GitHub. Hosted at landgreen.github.io/n-gon; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/n-gon.jpg', 1280, 800, 'center', '["assets/posters/n-gon.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -49, 1795485600000, 'Run, jump and shoot through physics-driven levels.', '', '', 1);
